// Золотой набор: к каждому вопросу id кусков, где лежит ответ
const golden = [
  { q: "Сколько дней на возврат?",          gold: ["c7"] },
  { q: "Какие способы оплаты и доставки?",  gold: ["c3", "c8"] },
  { q: "Можно ли вернуть уценённый товар?", gold: ["c11"] },
];
// Что вернул ретривер: top-20, лучший первым (здесь выписаны начала списков)
const pad = (xs) => [...xs, ...Array.from({ length: 20 - xs.length }, (_, i) => "x" + i)];
const retrieved = [
  pad(["c2", "c7", "c9", "c4", "c1"]),
  pad(["c3", "c5", "c6", "c8", "c0"]),
  pad(["c1", "c2", "c5", "c6", "c9", "c4", "c12", "c13", "c14", "c15", "c16", "c17", "c18", "c19", "c11"]),
];

const recallAt    = (ret, gold, k) => gold.filter((g) => ret.slice(0, k).includes(g)).length / gold.length;
const precisionAt = (ret, gold, k) => ret.slice(0, k).filter((id) => gold.includes(id)).length / k;
const rr = (ret, gold) => { const i = ret.findIndex((id) => gold.includes(id)); return i < 0 ? 0 : 1 / (i + 1); };
// context precision в духе RAGAS: среднее precision@k по позициям, где лежит нужный кусок
const ctxPrecision = (ret, gold, K) => {
  const hits = [];
  for (let k = 1; k <= K; k++) if (gold.includes(ret[k - 1])) hits.push(precisionAt(ret, gold, k));
  return hits.length ? hits.reduce((a, b) => a + b) / hits.length : 0;
};

const f = (x) => x.toFixed(2);
golden.forEach(({ gold }, i) => {
  const r = retrieved[i];
  console.log(i + 1, "recall@5", f(recallAt(r, gold, 5)), "recall@20", f(recallAt(r, gold, 20)),
    "precision@5", f(precisionAt(r, gold, 5)), "RR", f(rr(r, gold)), "ctxP@5", f(ctxPrecision(r, gold, 5)));
});
const mean = (fn) => f(golden.reduce((s, { gold }, i) => s + fn(retrieved[i], gold), 0) / golden.length);
console.log("mean recall@5", mean((r, g) => recallAt(r, g, 5)), "mean recall@20", mean((r, g) => recallAt(r, g, 20)), "MRR", mean(rr));

