import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // ключ из ANTHROPIC_API_KEY
const JUDGE_MODEL = process.env.JUDGE_MODEL!; // одна зафиксированная модель, чтобы числа были сравнимы

type Claim = { claim: string; supported: boolean; chunk: number | null };

export async function faithfulness(question: string, chunks: string[], answer: string) {
  const context = chunks.map((c, i) => "[" + (i + 1) + "] " + c).join("\n");
  const prompt = [
    "Split the ANSWER into atomic factual claims.",
    "For each claim decide: is it stated in, or directly implied by, one CONTEXT chunk?",
    "General knowledge does not count. When unsure, answer false.",
    'Return only JSON: {"claims":[{"claim":"...","supported":true,"chunk":1}]}',
    "QUESTION: " + question,
    "CONTEXT:\n" + context,
    "ANSWER: " + answer,
  ].join("\n");

  const msg = await client.messages.create({
    model: JUDGE_MODEL,
    max_tokens: 1024,
    messages: [{ role: "user", content: prompt }],
  });
  const text = msg.content.flatMap((b) => (b.type === "text" ? [b.text] : [])).join("");
  const claims: Claim[] = JSON.parse(text).claims; // может упасть: такие сбои тоже считай
  const supported = claims.filter((c) => c.supported).length;
  return {
    score: claims.length ? supported / claims.length : 1, // нет утверждений: нечему быть неподтверждённым
    unsupported: claims.filter((c) => !c.supported),
  };
}

